xml.Script:
        Colors[0] := 'A3E9FF'; // LightBlue
        Colors[1] := 'FFFF00'; // Yellow
        Colors[2] := 'FF0000'; // Red
        Colors[3] := '80287E'; // Purple
        Color := Colors[Random(4)];

        R  := 0.55;     // Cone radius
        H  := R * 1.09; // Cone Height
        K  := R * 0.4;  // Top Cut Depth
        TZ := R * 0.22; // Vertical Offset

        N := 60; // Quality of cones

        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        sAngle := 2 * Pi / 3;
        for i := 0 to 2 do begin
            ax[i] := sin(sAngle * (i + 0.25));
            ay[i] := cos(sAngle * (i + 0.25));
        end;
        az := -1/sqrt(8);
